-- ملف 13 من 16 — سلع 9601 إلى 10400 من إجمالي 12621
-- شغّل ملفات هذه السلسلة بالترتيب من 01 لآخر رقم. كل ملف مستقل وآمن (Upsert).

on conflict (hs_code) where hs_code is not null and hs_code <> '' do update set
  arabic_name = case when (public.commodities.arabic_name is null or public.commodities.arabic_name = '') and excluded.arabic_name is not null and excluded.arabic_name <> '' then excluded.arabic_name else public.commodities.arabic_name end,
  english_name = case when (public.commodities.english_name is null or public.commodities.english_name = '') and excluded.english_name is not null and excluded.english_name <> '' then excluded.english_name else public.commodities.english_name end,
  category = case when (public.commodities.category is null or public.commodities.category = '') and excluded.category is not null and excluded.category <> '' then excluded.category else public.commodities.category end,
  duty = case when (public.commodities.duty is null or public.commodities.duty = '') and excluded.duty is not null and excluded.duty <> '' then excluded.duty else public.commodities.duty end,
  updated_at = now();
